contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint256 amount) public {
        // Acquire a balance via the airdrop (fresh contract: caller is whitelisted).
        c.getTokens(); if (__ESBMC_reverted()) return;
        // Take ownership so burn() is callable from this test contract.
        c.transferOwnership(address(this)); if (__ESBMC_reverted()) return;
        require(amount > 0 && amount <= c.balanceOf(address(this)));

        uint256 supplyBefore = c.totalSupply(); if (__ESBMC_reverted()) return;
        uint256 distBefore = c.totalDistributed(); if (__ESBMC_reverted()) return;
        uint256 balBefore = c.balanceOf(address(this)); if (__ESBMC_reverted()) return;

        c.burn(amount); if (__ESBMC_reverted()) return;

        assert(c.balanceOf(address(this)) == balBefore - amount && c.totalSupply() == supplyBefore - amount && c.totalDistributed() == distBefore - amount);
    }

    receive() external payable {}
}

